    # Validating the input score to be within the expected range.
    if not (0 <= score <= 100):
        # Raising an error for scores outside the valid range.
        raise ValueError("Score must be between 0 and 100.")

    # Checking for an 'A' grade.
    if score >= 90:
        return 'A'
    # Checking for a 'B' grade.
    elif score >= 80:
        return 'B'
    # Checking for a 'C' grade.
    elif score >= 70:
        return 'C'
    # Checking for a 'D' grade.
    elif score >= 60:
        return 'D'
    # All other scores result in an 'F'.
    else:
        # This is the final possible grade.
        return 'F'

