def roman_to_int(roman_numeral):
    # A Dictionary stores the integer value for each Roman numeral character.
    roman_map = {'I': 1, 'V': 5, 'X': 10, 'L': 50, 'C': 100, 'D': 500, 'M': 1000}
    total = 0
    # The length of the input string is calculated once for efficiency.
    n = len(roman_numeral)

    # Loop through the Roman numeral string from left to right.
    for i in range(n):
        current_value = roman_map[roman_numeral[i]]
        # Check if there is a next character and if it represents a larger value.
        if i + 1 < n:
            next_value = roman_map[roman_numeral[i+1]]
            # If the current value is smaller than the next, it's a subtractive case.
            if current_value < next_value:
                total -= current_value
            else:
                # Otherwise, it's an additive case.
                total += current_value
        else:
            # The Last character is always added to the total.
            total += current_value
    # The Final integer equivalent is returned.
    return total

