    # Convert both strings to lowercase and remove spaces.
    s1_processed = s1.lower().replace(" ", "")
    s2_processed = s2.lower().replace(" ", "")

    # Initial check for different lengths.
    if len(s1_processed) != len(s2_processed):
        return False

    # Create character counts for the first string.
    char_counts = {}
    for char in s1_processed:
        char_counts[char] = char_counts.get(char, 0) + 1

    # Decrement counts based on the second string.
    for char in s2_processed:
        # Check if character exists in the counts.
        if char not in char_counts:
            return False
        char_counts[char] -= 1
        # Check if count drops below zero.
        if char_counts[char] < 0:
            return False

    # Final check: all counts must be zero.
    for count in char_counts.values():
        if count != 0:
            return False
    # If all checks pass, they are anagrams.
    return True

