def update_dict(dict1: dict, dict2: dict) -> dict:
    """
    Merges two dictionaries, updating values from the second dictionary
    into the first where keys overlap, and adding new keys from the second.
    """
    # Create a shallow copy of the first dictionary to avoid modifying the original.
    merged_dict = dict1.copy()

    # Iterate over key-value pairs in the second dictionary.
    for key, value in dict2.items():
        # Update existing keys or add new keys from the second dictionary.
        merged_dict[key] = value
    # Return the newly merged dictionary.
    return merged_dict

