def harmonic_mean(numbers: list[float]) -> float:
    # A. Ensure the input list is not empty to avoid division by zero.
    if not numbers:
        raise ValueError("Input list cannot be empty")

    reciprocal_sum = 0.0
    # B. Iterate through each number in the provided list.
    for num in numbers:
        # C. Check for positive numbers, as harmonic mean is undefined for non-positive.
        if num <= 0:
            raise ValueError("All numbers must be positive")
        # D. Calculate the reciprocal of the current number.
        reciprocal_sum += 1 / num

    # E. Calculate the arithmetic mean of the reciprocals.
    mean_of_reciprocals = reciprocal_sum / len(numbers)

    # F. Handle the case where the mean of reciprocals is zero, which implies an infinite harmonic mean.
    if mean_of_reciprocals == 0:
        # G. This scenario is theoretically impossible with positive inputs, but good for robustness.
        return float('inf') 

    # H. The harmonic mean is the reciprocal of the mean of reciprocals.
    return 1 / mean_of_reciprocals

