def is_valid_ipv4(ip_address: str) -> bool:
    # A. Split the IP address string by the dot character.
    octets = ip_address.split('.')
    # B. An IPv4 address must have exactly four octets.
    if len(octets) != 4:
        return False
    # C. Iterate through each octet to validate it.
    for octet_str in octets:
        # D. Check if the octet string is empty, which is invalid.
        if not octet_str:
            return False
        # E. Attempt to convert the octet string to an integer.
        try:
            octet = int(octet_str)
        except ValueError:
            # F. If conversion fails, it's not a valid number.
            return False
        # G. An octet must be between 0 and 255, inclusive.
        if not (0 <= octet <= 255):
            return False
        # H. Disallow leading zeros for numbers other than '0' itself.
        if len(octet_str) > 1 and octet_str[0] == '0':
            return False
    # I. If all checks pass, the IPv4 address is valid.
    return True

