    for char in reversed(roman_numeral):
        current_value = roman_map[char] # Get the integer value of the current character.

        # If the current value is less than the previous value, it's a subtractive case.
        if current_value < previous_value:
            integer_value -= current_value # Subtract the current value.
        else:
            integer_value += current_value # Otherwise, add the current value.
        previous_value = current_value # Update the previous value for the next iteration.

    # The final integer value is returned.
    return integer_value

