def check_password_strength(password):
    # A. Initialize criteria counters and flags.
    length_ok = len(password) >= 8
    has_upper = False
    has_lower = False
    has_digit = False

    # B. Iterate through the password to check character types.
    for char in password:
        if char.isupper():
            has_upper = True
        elif char.islower():
            has_lower = True
        elif char.isdigit():
            has_digit = True

    # C. Count how many character type criteria are met.
    criteria_met_count = sum([has_upper, has_lower, has_digit])

    # D. Determine strength based on length and criteria count.
    if length_ok and has_upper and has_lower and has_digit:
        return 'Strong' # E. All strong conditions met.

    # F. Check for medium strength conditions.
    if len(password) >= 6 and criteria_met_count >= 2:
        return 'Medium' # G. Medium conditions met.

    return 'Weak' # H. Default to weak if no other conditions are met.

